    self.ShadowAnimationCount = 0
    self.ReplayCount = 0
    self.ReplayHead = 0
    if Environment.__INK_GAME_AUTO_DODGE == self then
        Environment.__INK_GAME_AUTO_DODGE = nil
    end
end

State.HubOnly = true
return State
