        if not ok then
            self:SetEnabled(false)
            self.Status = "Stopped: " .. tostring(err)
            warn(self.Status)
        end
    end)
end

function state:Destroy()
    self:SetEnabled(false)
    self.Destroyed = true
    if env[key] == self then env[key] = nil end
end

env[key] = state
return state

