local function profileFor(player)
    local id = player.UserId or player.Name
    if not brain.Profiles[id] then brain.Profiles[id] = {Attacks = 0, Rushes = 0} end
    return brain.Profiles[id]
end

observeSwing = function(player, threat)
    if MODE ~= "combat" then return end
    local _, root = live(threat.Character)
    CombatPolicy.Observe(profileFor(player), threat.At, root and root.AssemblyLinearVelocity.Magnitude > 35)
end

local function dashReady()
    if not dashHandler then return false end
    local values = debug.getupvalues(dashHandler)
    return values[5] == false and values[6] == true
end

local function nativeLocomotion(character)
    for _, connection in ipairs(getconnections(UIS.InputBegan)) do
        local fn = connection.Function
        if type(fn) == "function" then
            local source = getfenv(fn).script
            if source and source.Name == "LocomotionController" then
                for _, value in pairs(debug.getupvalues(fn)) do
                    if type(value) == "table" and rawget(value, "Character") == character
                        and type(value.ToggleSprint) == "function" then return value end
                end
            end
        end
    end
end

local function restoreCombatCharacter()
    if brain.OwnConnection then brain.OwnConnection:Disconnect(); brain.OwnConnection = nil end
    if brain.JumpConnection then brain.JumpConnection:Disconnect(); brain.JumpConnection = nil end
    if brain.Humanoid and brain.Humanoid.Parent then brain.Humanoid.AutoRotate = brain.AutoRotate end
    if brain.Locomotion and brain.Locomotion.Character == LP.Character then
        brain.Locomotion.SprintKeyHeld = brain.SprintHeld
        pcall(brain.Locomotion.ToggleSprint, brain.Locomotion, brain.SprintHeld == true)
    end
    brain.Character, brain.Humanoid, brain.Locomotion = nil, nil, nil
end

local function bindCombatCharacter(character, humanoid)
    if brain.Character == character then return end
    restoreCombatCharacter()
    brain.Character, brain.Humanoid = character, humanoid
    brain.AutoRotate = humanoid.AutoRotate
    humanoid.AutoRotate = false
    brain.Locomotion = nativeLocomotion(character)
    brain.SprintHeld = brain.Locomotion and brain.Locomotion.SprintKeyHeld
    brain.LastHealth, brain.PendingOutcome = humanoid.Health, nil
    brain.LastPosition = character.HumanoidRootPart.Position
    brain.PendingPunch, brain.PendingDash = nil, nil
    local animator = humanoid:FindFirstChildOfClass("Animator")
    if animator then
        brain.OwnConnection = animator.AnimationPlayed:Connect(function(track)
            local id = track.Animation and track.Animation.AnimationId:match("%d+")
            local pending = brain.PendingPunch
            if attackIds[id] and pending and os.clock() - pending.At < .6 and not pending.Observed then
                pending.Observed = true
                S.ConfirmedAttacks += 1
                local root = character:FindFirstChild("HumanoidRootPart")
                if pending.DuringDash and root and root:FindFirstChild("DashVelocity") then S.ConfirmedDashPunches += 1 end
            end
        end)
    end
    brain.JumpConnection = humanoid.StateChanged:Connect(function(_, state)
        if state == Enum.HumanoidStateType.Jumping and os.clock() < (brain.JumpUntil or 0) + .2 then
            S.ConfirmedJumps += 1
        end
    end)
end

local function observeOutcome(humanoid, now)
    local damage = brain.LastHealth and math.max(0, brain.LastHealth - humanoid.Health) or 0
    brain.LastHealth = humanoid.Health
    local root = brain.Character and brain.Character:FindFirstChild("HumanoidRootPart")
    if root and brain.LastPosition and not movementRestricted(brain.Character) then
        local delta = root.Position - brain.LastPosition
        local distance = Vector3.new(delta.X, 0, delta.Z).Magnitude
        if distance < 50 and brain.PreviousDesired and brain.PreviousDesired.Magnitude > .1 then S.MovedStuds += distance end
    end
    if root then brain.LastPosition = root.Position end
    S.DamageObserved += damage
    local pending = brain.PendingOutcome
    if pending then
        if damage > 0 and now - pending.At <= .5 then
            local field = pending.Side < 0 and "LeftDamage" or "RightDamage"
            pending.Profile[field] = math.min(1000, (pending.Profile[field] or 0) + damage)
            brain.PendingOutcome = nil
        elseif now - pending.At > .5 then brain.PendingOutcome = nil end
    end
    if brain.PendingDash then
        if brain.Character and brain.Character:FindFirstChild("HumanoidRootPart")
            and brain.Character.HumanoidRootPart:FindFirstChild("DashVelocity") then
            S.ConfirmedDashes += 1
            brain.PendingDash = nil
        elseif now - brain.PendingDash > .4 then brain.PendingDash = nil end
    end
end

local function watchWarning(part)
    if not part:IsA("BasePart") or not part.Name:match("^RubberGodMove1Warning_")
        or part:GetAttribute("RubberGodVFX") ~= true then return end
    if LP.Character and part.Name == "RubberGodMove1Warning_" .. LP.Character.Name then return end
    brain.Warnings[part] = {Used = false}
end

local function prepareAdvancedCombat()
    local module = LP.PlayerScripts:FindFirstChild("PlayerModule")
    assert(module, "Native movement not ready")
    local controls = require(module):GetControls()
    brain.Controls = controls
    brain.Desired = Vector3.zero
    brain.MapHazards = {}
    for _, name in ipairs({"FallKillPart", "FallPart"}) do
        local part = workspace:FindFirstChild(name)
        if part and part:IsA("BasePart") then brain.MapHazards[#brain.MapHazards + 1] = part end
    end
    brain.RenderName = "AllenSkyCombatMovement"
    Run:BindToRenderStep(brain.RenderName, Enum.RenderPriority.Input.Value + 1, function()
        if not S.Enabled then return end
        local character = LP.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health <= 0 then return end
        if movementRestricted(character) then humanoid:Move(Vector3.zero, false); return end
        if not controls.activeController or not controls.activeController.enabled then return end
        humanoid:Move(brain.Desired, false)
        if os.clock() < (brain.JumpUntil or 0) then humanoid.Jump = true end
        S.MotorFrames += 1
    end)
    local external = env.__ALLEN_MATCH_dodge
    if external and external.Enabled then
        external:SetEnabled(false)
        brain.ExternalDodge, brain.ExternalGeneration = external, external.Generation
    end
    local qte = env.__ALLEN_MATCH_qte
    if qte and qte.Enabled then
        qte:SetEnabled(false)
        brain.ExternalQte, brain.ExternalQteGeneration = qte, qte.Generation
    end
    local item = env.__ALLEN_MATCH_dodgeitem
    if item and item.Enabled then
        item:SetEnabled(false)
        brain.ExternalItem, brain.ExternalItemGeneration = item, item.Generation
    end
    for _, child in ipairs(workspace:GetChildren()) do watchWarning(child) end
    brain.WarningConnection = workspace.ChildAdded:Connect(watchWarning)
    prepareItemDodge()
end

local function warningThreat(root)
    for part, record in pairs(brain.Warnings) do
        if not part:IsDescendantOf(workspace) then brain.Warnings[part] = nil
        else
            local point = part.CFrame:PointToObjectSpace(root.Position)
            -- RubberGodConfig.Move1 uses a 12-stud square and 24-stud height.
            if math.abs(point.X) < 8 and math.abs(point.Z) < 8 and point.Y > -4 and point.Y < 25 then
                return record, part.Position
            end
        end
    end
end

local function scanCombatTarget(root, now)
    if now < brain.TargetScan and brain.Target and live(brain.Target.Character) then return brain.Target end
    brain.TargetScan = now + .2
    local chosen, best = nil, 45
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LP then
            local _, other = live(player.Character)
            if other and not States.HasAny(player.Character, {"DamageImmune", "Ragdolled", "CombatDisabled"}) then
                local distance = (other.Position - root.Position).Magnitude
                if player == brain.Target then distance *= .8 end
                if distance < best then chosen, best = player, distance end
            end
        end
    end
    brain.Target = chosen
    return chosen
end

impendingThreat = function(root, now)
    updatePing(now)
    local lead = CombatPolicy.LeadTime(S.PingMs, (S.FrameMs or 16.7) / 1000)
    local selected, selectedRoot, bestEta
    local waitingGun = false
    for player, threat in pairs(threats) do
        local _, attacker = live(threat.Character)
        local reported = ThreatPolicy.ReportFresh(threat, now)
        local playing = threat.Track and threat.Track.IsPlaying
        if not attacker or player.Character ~= threat.Character or now - threat.At > 1.5
            or (not playing and not reported) then
            threats[player] = nil
        elseif ThreatPolicy.Eligible(threat, now) then
            local eta
            if reported and overlapsCharacter(threat.Reported.CFrame, threat.Reported.Size, LP.Character) then
                eta = 0
                threat.Evidence = "Native hitbox"
            elseif playing and not ThreatPolicy.PredictAnimation(threat.Kind) then
                waitingGun = true
            elseif playing then
                local speed = math.max(.1, threat.Track.Speed)
                local contact = threat.Contact or .16
                if not threat.ContactVerified then
                    local ok, marker = pcall(threat.Track.GetTimeOfKeyframe, threat.Track, "Start")
                    if ok and type(marker) == "number" and marker > 0 and marker < 1 then
                        contact, threat.Contact, threat.ContactVerified = marker, marker, true
                    end
                end
                local candidate = (contact - threat.Track.TimePosition) / speed
                if ThreatPolicy.WithinContactWindow(candidate, lead) then
                    local relative = attacker.AssemblyLinearVelocity - root.AssemblyLinearVelocity
                    local size = hitboxSizes[threat.Kind]
                    -- Predict at contact, not "overlapping now OR at contact".
                    -- Ignore teleport-like velocity samples rather than inventing a collision.
                    if size and relative.Magnitude <= 180 then
                        local horizon = math.max(0, candidate)
                        local cf = attacker.CFrame * hitboxOffset + relative * horizon
                        if overlapsCharacter(cf, size, LP.Character) then
                            local params = RaycastParams.new()
                            params.FilterType = Enum.RaycastFilterType.Exclude
                            params.RespectCanCollide = true
                            params.FilterDescendantsInstances = {LP.Character, threat.Character}
                            local obstructed = workspace:Raycast(attacker.Position, root.Position - attacker.Position, params)
                            if not obstructed then
                                eta = horizon
                                threat.Evidence = "Predicted contact"
                            end
                        end
                    end
                end
            end
            if eta and (not bestEta or eta < bestEta) then
                selected, selectedRoot, bestEta = threat, attacker, eta
            end
        end
    end
    S.ThreatStatus = selected and selected.Evidence
        or waitingGun and "Gun: waiting for a confirmed overlapping hitbox"
        or "Watching attack contact"
    return selected, selectedRoot, bestEta
end

local function routeClear(root, vector, target, length)
    if vector.Magnitude < .05 then return false end
    local direction = vector.Unit
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.RespectCanCollide = true
    params.FilterDescendantsInstances = target and {LP.Character, target} or {LP.Character}
    local distance = length or 4
    if workspace:Raycast(root.Position, direction * distance, params) then return false end
    for _, offset in ipairs({math.min(3, distance), distance}) do
        local floor = workspace:Raycast(root.Position + direction * offset, Vector3.new(0, -10, 0), params)
        if not floor or floor.Normal.Y < .6 or floor.Instance.Name == "FallKillPart" or floor.Instance.Name == "FallPart" then return false end
        if brain.MapHazards and #brain.MapHazards > 0 then
            local hazards = RaycastParams.new()
            hazards.FilterType = Enum.RaycastFilterType.Include
            hazards.FilterDescendantsInstances = brain.MapHazards
            local from = root.Position + direction * offset
            if workspace:Raycast(from, floor.Position - from, hazards) then return false end
        end
    end
    return true
end

local function requestJump(humanoid, now)
    local height = humanoid.UseJumpPower and humanoid.JumpPower ^ 2 / (2 * math.max(.1, workspace.Gravity)) or humanoid.JumpHeight
    if now < brain.NextJump or humanoid.FloorMaterial == Enum.Material.Air
        or not height or height <= 0
        or States.HasAny(LP.Character, {"JumpDisabled", "Stunned", "Ragdolled", "MovementInputDisabled"}) then return false end
    humanoid.Jump = true
    brain.JumpUntil = now + .15
    brain.NextJump = now + 1.1
    S.JumpRequests += 1
    return true
end

local function planMapRoute(humanoid, root, destination, now)
    if brain.PathBusy or now < (brain.NextPath or 0) then return end
    brain.NextPath = now + 1.2
    local job = {}
    brain.PathBusy = job
    local character, generation = LP.Character, S.Generation
    task.spawn(function()
        local height = humanoid.UseJumpPower and humanoid.JumpPower ^ 2 / (2 * math.max(.1, workspace.Gravity)) or humanoid.JumpHeight
        local path = game:GetService("PathfindingService"):CreatePath({AgentRadius = 2, AgentHeight = 5,
            AgentCanJump = height >= 3, AgentCanClimb = true, WaypointSpacing = 4})
        local ok = pcall(path.ComputeAsync, path, root.Position, destination)
        if brain.PathBusy ~= job then return end
        brain.PathBusy = nil
        if not S.Enabled or generation ~= S.Generation or LP.Character ~= character then return end
        if not brain.RequestedGoal or (brain.RequestedGoal - destination).Magnitude > 6 then brain.NextPath = 0; return end
        if brain.PathBlocked then brain.PathBlocked:Disconnect(); brain.PathBlocked = nil end
        if ok and path.Status == Enum.PathStatus.Success then
            brain.PathPoints, brain.PathIndex, brain.PathGoal = path:GetWaypoints(), 2, destination
            brain.PathAt = os.clock()
            brain.PathBlocked = path.Blocked:Connect(function(index)
                if index >= (brain.PathIndex or 1) then brain.PathPoints = nil; brain.NextPath = 0 end
            end)
        else brain.PathPoints = nil end
    end)
end

local function mapDirection(humanoid, root, target, toward, now)
    brain.RequestedGoal = target.Position
    if routeClear(root, toward, target.Parent, math.min(6, (target.Position - root.Position).Magnitude))
        and math.abs(target.Position.Y - root.Position.Y) < 3 then S.Navigation = "direct"; return toward end
    if not brain.PathPoints or not brain.PathGoal or (brain.PathGoal - target.Position).Magnitude > 6
        or now - (brain.PathAt or 0) > 3 then
        brain.PathPoints = nil
        planMapRoute(humanoid, root, target.Position, now)
    end
    local points = brain.PathPoints
    local index = brain.PathIndex or 2
    if points then
        while points[index] and (points[index].Position - root.Position).Magnitude < 3 do index += 1 end
        brain.PathIndex = index
        local point = points[index]
        if point then
            local direction = point.Position - root.Position
            direction = Vector3.new(direction.X, 0, direction.Z)
            if direction.Magnitude > .1 then
                if point.Action == Enum.PathWaypointAction.Jump then requestJump(humanoid, now) end
                S.Navigation = "path"
                return direction.Unit
            end
        end
    end
    S.Navigation = brain.PathBusy and "planning" or "blocked"
    return toward
end

local function jumpObstacle(humanoid, root, direction, target, now)
    if now < brain.NextJump or humanoid.FloorMaterial == Enum.Material.Air
        or States.HasAny(LP.Character, {"JumpDisabled", "Stunned", "Ragdolled", "MovementInputDisabled"}) then return false end
    local height = humanoid.UseJumpPower and humanoid.JumpPower ^ 2 / (2 * workspace.Gravity) or humanoid.JumpHeight
    if height < 3 or direction.Magnitude < .1 then return false end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = target and {LP.Character, target} or {LP.Character}
    local forward = direction.Unit * 3
    local lower = workspace:Raycast(root.Position - Vector3.new(0, 1.5, 0), forward, params)
    local upper = workspace:Raycast(root.Position + Vector3.new(0, math.min(3, height - 1), 0), forward, params)
    local landing = workspace:Raycast(root.Position + forward + Vector3.new(0, 3, 0), Vector3.new(0, -12, 0), params)
    if lower and not upper and landing and landing.Normal.Y > .6 then
        if not requestJump(humanoid, now) then return false end
        brain.Desired = direction.Unit
        humanoid:Move(direction.Unit, false)
        return true
    end
    return false
end

local function moveCombat(humanoid, root, candidates, target, now)
    for _, direction in ipairs(candidates) do
        if routeClear(root, direction, target, 4) then
            brain.Desired = direction.Magnitude > 1 and direction.Unit or direction
            humanoid:Move(brain.Desired, false)
            S.Moving = LP.Character
            brain.LastMove = now
            return direction
        end
    end
    if candidates[1] and jumpObstacle(humanoid, root, candidates[1], target, now) then return candidates[1] end
    brain.Desired = Vector3.zero
    humanoid:Move(Vector3.zero, false)
    return Vector3.zero
end

local function requestCombatDash(humanoid, root, direction, target, record, now)
    -- Auto Dash removed at user request. Manual dash remains native to the game.
    return false
end

local itemState = {NextAttempt = 0, Dispatcher = nil, Character = nil, NextInspect = 0, ActiveUntil = 0}
local itemDefinition
S.DodgeTrace = {}
local function traceDodge(reason, record)
    local now = os.clock()
    local previous = S.DodgeTrace[#S.DodgeTrace]
    if previous and previous.Reason == reason and now - previous.At < .25 then return end
    if #S.DodgeTrace >= 120 then table.remove(S.DodgeTrace, 1) end
    S.DodgeTrace[#S.DodgeTrace + 1] = {At = now, Reason = reason,
        Evidence = record and record.Evidence, Kind = record and record.Kind}
end
S.ItemRequests, S.ItemAccepted, S.ItemDodged, S.ItemMissed = 0, 0, 0, 0

local function ownedDodgeItem(character)
    for _, container in ipairs({character, LP.Backpack}) do
        for _, tool in ipairs(container:GetChildren()) do
            if tool:IsA("Tool") and tool:GetAttribute("PowerId") == "Flowstate"
                and (tool:GetAttribute("MoveId") == "Dodge" or tool.Name == "Dodge") then return tool end
        end
    end
end

local function findItemDispatcher(character, now)
    if itemState.Character ~= character then
        itemState.Character, itemState.Dispatcher, itemState.NextInspect = character, nil, 0
    end
    if itemState.Character == character and itemState.Dispatcher then return itemState.Dispatcher end
    if now < itemState.NextInspect then return end
    itemState.NextInspect = now + 2
    if type(getgc) ~= "function" then S.ItemStatus = "Executor needs getgc support"; return end
    local endpoint = RS.Remotes.Gameplay.Combat.HotbarToolInput
    local found
    for _, fn in ipairs(getgc()) do
        if type(fn) == "function" and (type(islclosure) ~= "function" or islclosure(fn)) and debug.info(fn, "n") == "dispatchHotbarInput" then
            local source = getfenv(fn).script
            if source and source.Name == "BackpackUI" then
                local values = debug.getupvalues(fn)
                if values[4] == LP and values[5] == character and values[7] == endpoint then
                    if found then S.ItemStatus = "Ambiguous native hotbar dispatcher"; return end
                    found = fn
                end
            end
        end
    end
    itemState.Dispatcher, itemState.Character = found, character
    return found
end

local function restoreItemEquip()
    local lease = itemState.Equip
    itemState.Equip = nil
    if not lease or LP.Character ~= lease.Character then return end
    local humanoid = lease.Character:FindFirstChildOfClass("Humanoid")
    if not humanoid or humanoid.Health <= 0 or lease.Tool.Parent ~= lease.Character then return end
    if lease.Previous and lease.Previous.Parent == LP.Backpack then humanoid:EquipTool(lease.Previous)
    else humanoid:UnequipTools() end
end

local function itemNotify(command, payload)
    if S.Enabled and command == "Broken" then
        S.ItemBroken = (S.ItemBroken or 0) + 1
        traceDodge("Flowstate stacks lost to damage")
        return
    end
    if not S.Enabled or not itemState.Pending or os.clock() - itemState.Pending.At > 2 then return end
    local now = os.clock()
    traceDodge("Native feedback: " .. tostring(command))
    if command == "Accepted" and not itemState.Pending.Accepted then
        itemState.Pending.Accepted = true
        itemState.ActiveUntil = now + (type(payload) == "number" and payload or itemDefinition.Window)
        S.ItemAccepted += 1
        restoreItemEquip()
    elseif command == "Dodged" then
        S.ItemDodged += 1
        itemState.ActiveUntil = now + (itemDefinition.SuccessImmunity or .9)
        itemState.NextAttempt = now + itemDefinition.SuccessCooldown
        itemState.Pending = nil
        restoreItemEquip()
    elseif command == "Missed" then
        S.ItemMissed += 1
        itemState.ActiveUntil = 0
        itemState.NextAttempt = now + itemDefinition.MissCooldown
        itemState.Pending = nil
        restoreItemEquip()
    end
end

prepareItemDodge = function()
    local powers = gameplay:FindFirstChild("Powers")
    local flow = powers and powers:FindFirstChild("Flowstate")
    local definition = flow and flow:FindFirstChild("Definition")
    assert(definition, "Join a Sky Fighters combat round to use the Dodge item")
    itemDefinition = require(definition).Dodge
    local character = LP.Character
    if character and ownedDodgeItem(character) then findItemDispatcher(character, os.clock()) end
end

local function bindItemFeedback(tool)
    if itemState.NotifyTool == tool and itemState.NotifyConnection and itemState.NotifyConnection.Connected then return true end
    if itemState.NotifyConnection then itemState.NotifyConnection:Disconnect(); itemState.NotifyConnection = nil end
    local runtime = tool:FindFirstChild("PowerRuntimeRemotes")
    local notify = runtime and runtime:FindFirstChild("Notify")
    if not notify or not notify:IsA("RemoteEvent") then return false end
    if itemState.ReadyConnection then itemState.ReadyConnection:Disconnect() end
    itemState.NotifyTool = tool
    itemState.NotifyConnection = notify.OnClientEvent:Connect(itemNotify)
    itemState.ReadyConnection = tool:GetAttributeChangedSignal("OnCooldown"):Connect(function()
        if not tool:GetAttribute("OnCooldown") and not itemState.Pending then
            itemState.NextAttempt = 0
            if wakeItemDodge then wakeItemDodge() end
        end
    end)
    return true
end

usableDodgeItem = function(character, now)
    if itemState.Pending and now - itemState.Pending.At > 1.2 then itemState.Pending = nil; restoreItemEquip() end
    local tool = character and ownedDodgeItem(character)
    if tool then
        local cooling = tool:GetAttribute("OnCooldown") == true
        if itemState.CooldownTool ~= tool then
            itemState.CooldownTool, itemState.WasCooling = tool, cooling
        else
            -- Server cooldown completion overrides a timer started on delayed feedback.
            if itemState.WasCooling and not cooling and not itemState.Pending then
                itemState.NextAttempt = 0
            end
            itemState.WasCooling = cooling
        end
    end
    S.ItemWindowActive = character and (now < itemState.ActiveUntil or States.HasAny(character, {"Dodging"})) or false
    local reason = "Waiting for character"
    if character then reason = dodgeBlockReason(character) end
    if S.ItemWindowActive then
        S.ItemReady = false
        S.ItemStatus = "Native dodge window active"
        return
    end
    if reason then
        S.ItemReady = false
        S.ItemStatus = reason
        return
    end
    if not tool then S.ItemStatus = "Flowstate Dodge item required"; S.ItemReady = false; return end
    if not bindItemFeedback(tool) then S.ItemStatus = "Waiting for native Dodge item runtime"; S.ItemReady = false; return end
    local ready = not tool:GetAttribute("OnCooldown") and tool:GetAttribute("CombatRulesBlocked") ~= true
        and tool.Enabled and now >= itemState.NextAttempt
        and not itemState.Pending and not States.HasAny(character, {"Dodging"})
    S.ItemReady = ready == true
    S.ItemStatus = ready and "Dodge item ready"
        or itemState.Pending and "Waiting for server confirmation"
        or tool:GetAttribute("OnCooldown") and "Server Dodge cooldown"
        or tool:GetAttribute("CombatRulesBlocked") == true and "Native combat rules block Dodge"
        or not tool.Enabled and "Dodge tool disabled"
        or now < itemState.NextAttempt and "Dodge feedback cooldown"
        or "Native dodge item unavailable"
    return ready and tool or nil
end

tryItemDodge = function(character, root, record, now)
    if not record or not ThreatPolicy.Eligible(record, now) then return false end
    local tool = usableDodgeItem(character, now)
    if not tool then traceDodge(S.ItemStatus or "Item unavailable", record); return false end
    local current = impendingThreat(root, now)
    if current ~= record then return false end
    local dispatcher = findItemDispatcher(character, now)
    if not dispatcher then S.ItemStatus = "Native hotbar dispatcher not ready"; return false end
    local quick = tool:GetAttribute("QuickUse") == true
    if tool.Parent ~= character and not quick then
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        itemState.Equip = {Character = character, Previous = character:FindFirstChildOfClass("Tool"), Tool = tool}
        humanoid:EquipTool(tool)
        if tool.Parent ~= character then restoreItemEquip(); return false end
    end
    -- Equipping can alter state; validate the same threat again immediately before dispatch.
    if impendingThreat(root, os.clock()) ~= record or dodgeBlockReason(character) then
        restoreItemEquip()
        return false
    end
    record.ItemAttempts = (record.ItemAttempts or 0) + 1
    record.ItemAttempted = true
    local pending = {At = now, Tool = tool, Dispatcher = dispatcher, Quick = quick}
    itemState.Pending = pending
    itemState.NextAttempt = now + itemDefinition.Window + .15
    local ok, accepted = pcall(dispatcher, tool, "Begin", Enum.UserInputType.MouseButton1, quick)
    if not ok or accepted ~= true then
        itemState.Pending = nil
        record.ItemAttempted = false
        record.RetryAt = now + 1/120
        itemState.NextAttempt = record.RetryAt
        restoreItemEquip()
        S.ItemStatus = ok and "Native hotbar declined activation" or "Native hotbar activation failed"
        traceDodge(S.ItemStatus, record)
        return false
    end
    record.Used = true
    S.ItemRequests += 1
    traceDodge("Native activation requested", record)
    S.ItemStatus = "Dodge item requested · waiting for native confirmation"
    local generation = S.Generation
    task.delay(.05, function()
        if S.Enabled and S.Generation == generation and tool.Parent then
            pcall(dispatcher, tool, "End", Enum.UserInputType.MouseButton1, quick)
        end
    end)
    return true
end

itemDodgeStep = function(now)
    local full = env.__ALLEN_MATCH_combat
    if full and full.Enabled then status("Full Auto Combat manages the dodge item"); return end
    if now >= nextScan then nextScan = now + .4; scanThreats() end
    local character = LP.Character
    local humanoid, root = live(character)
    if not root then status("Dodge item waiting for character"); return end
    usableDodgeItem(character, now)
    local record, attacker, eta = impendingThreat(root, now)
    if record then
        local active = now < itemState.ActiveUntil or States.HasAny(character, {"Dodging"})
        if not active then
            -- Dodge item only. Native cooldown and pending feedback still apply.
            if not itemState.Pending then tryItemDodge(character, root, record, now) end
        end
    end
    status(S.ItemReady and ("Ready · " .. (S.ThreatStatus or "Watching native hitbox threats"))
        or S.ItemStatus or "Watching native hitbox threats")
end

local immediateBusy = false
wakeItemDodge = function()
    if MODE ~= "dodgeitem" or not S.Enabled or S.Destroyed or immediateBusy then return end
    local full = env.__ALLEN_MATCH_combat
    if full and full.Enabled then return end
    immediateBusy = true
    local ok, err = pcall(function()
        local character = LP.Character
        local _, root = live(character)
        if not root or not usableDodgeItem(character, os.clock()) then return end
        local record = impendingThreat(root, os.clock())
        if record then
            S.InstantChecks = (S.InstantChecks or 0) + 1
            tryItemDodge(character, root, record, os.clock())
        end
    end)
    immediateBusy = false
    if not ok then S.ItemStatus = "Immediate check failed: " .. tostring(err) end
end

stopItemDodge = function()
    if itemState.ReadyConnection then itemState.ReadyConnection:Disconnect(); itemState.ReadyConnection = nil end
    local pending = itemState.Pending
    if pending and pending.Tool.Parent then
        pcall(pending.Dispatcher, pending.Tool, "End", Enum.UserInputType.MouseButton1, pending.Quick)
    end
    restoreItemEquip()
    if itemState.NotifyConnection then itemState.NotifyConnection:Disconnect(); itemState.NotifyConnection = nil end
    itemState.NotifyTool = nil
    itemState.Pending = nil
    itemState.ActiveUntil = 0
    S.ItemReady, S.ItemWindowActive = false, false
end


local function combatStep(now)
    brain.PreviousDesired = brain.Desired
    brain.Desired = Vector3.zero
    local character = LP.Character
    local humanoid, root = live(character)
    if not root then status("Combat waiting for character"); return end
    bindCombatCharacter(character, humanoid)
    observeOutcome(humanoid, now)
    local readyDodgeItem = usableDodgeItem(character, now)
    if now >= nextScan then
        nextScan = now + .4
        scanThreats()
        local present = {}
        for _, p in ipairs(Players:GetPlayers()) do present[p.UserId or p.Name] = true end
        for id in pairs(brain.Profiles) do if not present[id] then brain.Profiles[id] = nil end end
    end
    local movementBlocked = movementRestricted(character)
    if movementBlocked then
        humanoid:Move(Vector3.zero, false)
        status("Combat waiting for native recovery")
        return
    end
    local player = scanCombatTarget(root, now)
    local targetRoot
    if player then local _, target = live(player.Character); targetRoot = target end
    if not targetRoot then
        humanoid:Move(Vector3.zero, false)
        status("Combat waiting for an opponent")
        return
    end
    local profile = profileFor(player)
    local flat = Vector3.new(targetRoot.Position.X - root.Position.X, 0, targetRoot.Position.Z - root.Position.Z)
    if flat.Magnitude < .1 then return end
    local toward = flat.Unit
    root.CFrame = CFrame.lookAt(root.Position, root.Position + toward)
    local side = toward:Cross(Vector3.yAxis)
    local sideSign = CombatPolicy.PreferredSide(profile, math.floor(now / 1.3) % 2 == 0 and 1 or -1)
    local warning, warningPosition = warningThreat(root)
    local threat, attacker = impendingThreat(root, now)
    local away = -toward
    if warningPosition then
        local delta = root.Position - warningPosition
        away = Vector3.new(delta.X, 0, delta.Z)
        if away.Magnitude < .1 then away = side end
        away = away.Unit
    elseif attacker then
        local delta = root.Position - attacker.Position
        local horizontal = Vector3.new(delta.X, 0, delta.Z)
        if horizontal.Magnitude > .1 then away = horizontal.Unit end
    end
    local tool
    for _, container in ipairs({character, LP.Backpack}) do
        for _, candidate in ipairs(container:GetChildren()) do
            if candidate:IsA("Tool") and (candidate.Name == "Fists" or candidate.Name == "Pole") then tool = candidate; break end
        end
        if tool then break end
    end
    if tool and tool.Parent ~= character and not itemState.Equip then humanoid:EquipTool(tool) end
    local size = tool and hitboxSizes[tool.Name]
    local canHit = size and overlapsCharacter(root.CFrame * hitboxOffset, size, player.Character) or false
    local targetVelocity = Vector3.new(targetRoot.AssemblyLinearVelocity.X, 0, targetRoot.AssemblyLinearVelocity.Z)
    local rushProne = profile.Attacks >= 3 and profile.Rushes / profile.Attacks > .5
    local rushing = targetVelocity:Dot(-toward) > 12 and (targetVelocity.Magnitude > 35 or rushProne)
    local ownDashing = root:FindFirstChild("DashVelocity") ~= nil
    local interval = profile.Interval
    local expected = interval and (profile.IntervalSamples or 0) >= 3 and profile.LastAttack
        and now - profile.LastAttack < interval and interval - (now - profile.LastAttack) < .18
    local record = threats[player]
    local recovering = record and record.Track.IsPlaying and record.Track.TimePosition > (record.Contact or .16) + .1
    local nearby = 0
    for p, watch in pairs(watches) do
        local _, other = live(p.Character)
        if other and (other.Position - root.Position).Magnitude < 10 then nearby += 1 end
    end
    local snapshot = {
        Target = true, Blocked = false, Threat = threat ~= nil, Warning = warning ~= nil,
        FreshThreat = warning and not warning.Used or threat and not threat.Used or false,
        CanItem = S.ItemDodgeEnabled and readyDodgeItem ~= nil,
        ItemWindow = now < itemState.ActiveUntil or States.HasAny(character, {"Dodging"}),
        CanDash = false, Health = humanoid.Health / math.max(1, humanoid.MaxHealth),
        NearbyEnemies = nearby, TargetRushing = rushing, Distance = flat.Magnitude, Reach = size and size.Z / 2 + 4 or 6,
        CanHit = canHit, CanPunch = tool ~= nil and tool.Parent == character and not itemState.Equip
            and not blocked(character) and not tool:GetAttribute("OnCooldown") and now >= brain.NextPunch,
        ExpectedAttackSoon = expected == true, OwnDashing = ownDashing, TargetVulnerable = recovering == true,
        SafeLongRoute = routeClear(root, toward, player.Character, 20)
    }
    local decision = CombatPolicy.Decide(snapshot)
    S.Navigation = "local footwork"
    S.Decision, S.TargetName, S.ObservedAttacks = decision, player.Name, profile.Attacks
    if brain.Locomotion and now >= brain.NextSprint then
        brain.NextSprint = now + .25
        brain.Locomotion.SprintKeyHeld = true
        brain.Locomotion:ToggleSprint(true)
    end
    local move
    if decision == "use_dodge_item" then
        if tryItemDodge(character, root, threat, now) then
            brain.Desired = Vector3.zero
            humanoid:Move(Vector3.zero, false)
        else moveCombat(humanoid, root, {side * sideSign, -side * sideSign, away}, player.Character, now) end
    elseif decision == "dodge_window" then
        brain.Desired = Vector3.zero
        humanoid:Move(Vector3.zero, false)
    elseif decision == "evade_dash" or decision == "evade" or decision == "sidestep" then
        move = moveCombat(humanoid, root, warning and {away, side * sideSign, -side * sideSign}
            or {side * sideSign, -side * sideSign, away}, player.Character, now)
        if decision == "evade_dash" and move.Magnitude > .1 then
            if requestCombatDash(humanoid, root, move, player.Character, warning or threat, now) then
                local field = sideSign < 0 and "LeftUses" or "RightUses"
                profile[field] = math.min(1000, (profile[field] or 0) + 1)
                brain.PendingOutcome = {At = now, Side = sideSign, Profile = profile}
            end
        end
    elseif decision == "retreat" or decision == "space" then
        moveCombat(humanoid, root, {-toward + side * sideSign * .3, side * sideSign, -side * sideSign}, player.Character, now)
    elseif decision == "approach" or decision == "approach_dash" then
        local route = mapDirection(humanoid, root, targetRoot, toward, now)
        move = moveCombat(humanoid, root, {route, route + side * .7, route - side * .7}, player.Character, now)
        if decision == "approach_dash" and move.Magnitude > .1 then
            requestCombatDash(humanoid, root, move, player.Character, {}, now)
        end
    elseif decision == "circle" or decision == "strike" then
        if not ownDashing then moveCombat(humanoid, root, {side * sideSign * .45, -side * sideSign * .45}, player.Character, now) end
    end
    if decision == "strike" and tool then
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = {character, player.Character}
        if not workspace:Raycast(root.Position, targetRoot.Position - root.Position, params) then
            local activation = tool:FindFirstChild("HotbarActivated")
            if activation and activation:IsA("BindableEvent") then
                brain.PendingPunch = {At = now, Observed = false, DuringDash = ownDashing}
                activation:Fire()
                local release = tool:FindFirstChild("HotbarDeactivated")
                if release and release:IsA("BindableEvent") then release:Fire() end
                brain.NextPunch = now + .22
                S.AttackRequests += 1
                if ownDashing then S.DashPunchRequests += 1 end
            end
        end
    end
    status(decision .. " · " .. player.Name .. " · " .. profile.Attacks .. " observed swings" .. (tool and "" or " · equip Fists / Pole"))
end

local function stopAdvancedCombat()
    stopItemDodge()
    brain.Desired = Vector3.zero
    if brain.RenderName then Run:UnbindFromRenderStep(brain.RenderName); brain.RenderName = nil end
    brain.Controls = nil
    restoreCombatCharacter()
    if brain.WarningConnection then brain.WarningConnection:Disconnect(); brain.WarningConnection = nil end
    brain.PendingPunch, brain.PendingDash, brain.PendingOutcome = nil, nil, nil
    brain.PathBusy, brain.PathPoints = nil, nil
    if brain.PathBlocked then brain.PathBlocked:Disconnect(); brain.PathBlocked = nil end
    table.clear(brain.Warnings)
    local external = brain.ExternalDodge
    if external and not external.Destroyed and external.Generation == brain.ExternalGeneration and not external.Enabled then
        external:SetEnabled(true)
    end
    brain.ExternalDodge = nil
    local qte = brain.ExternalQte
    if qte and not qte.Destroyed and qte.Generation == brain.ExternalQteGeneration and not qte.Enabled then qte:SetEnabled(true) end
    brain.ExternalQte = nil
    local item = brain.ExternalItem
    if item and not item.Destroyed and item.Generation == brain.ExternalItemGeneration and not item.Enabled then item:SetEnabled(true) end
    brain.ExternalItem = nil
end


local function defenseStep(now)
    local full = env.__ALLEN_MATCH_combat
    if full and full.Enabled then status("Full Auto Combat controls defense"); return end
    local item = env.__ALLEN_MATCH_dodgeitem
    if item and item.Enabled then status("Auto Dodge controls defense"); return end
    if now >= nextScan then nextScan = now + .5; scanThreats() end
    local character = LP.Character
    local humanoid, root = live(character)
    if not root or blocked(character) then status("Defense waiting for recovery"); return end
    local threat, other = activeThreat(root)
    if not threat then status("Watching fighting-style hitboxes"); return end
    S.DefendingUntil = now + .2
    status("Incoming melee · " .. other.Parent.Name)

end

local qteLibrary, originalQteNew, wrappedQteNew, nativeQtePress
local function prepareQte()
    qteLibrary = require(gameplay.QTEManager.QuickTimeEvents)
    originalQteNew = qteLibrary.new
    for _, value in pairs(debug.getupvalues(originalQteNew)) do
        if type(value) == "function" and debug.info(value, "n") == "Pressed" then
            nativeQtePress = value
            break
        end
    end
    assert(nativeQtePress, "Native QTE input function changed")
    wrappedQteNew = function(...)
        local args = table.pack(...)
        local object = originalQteNew(...)
        if S.Enabled then
            local duration = tonumber(args[3])
            if not duration or duration <= .1 then duration = qteLibrary.DefaultDuration end
            qteCallbacks[object] = {
                Deadline = tick() + duration,
                Window = (tonumber(args[7]) or .28) * 2
            }
        end
        return object
    end
    qteLibrary.new = wrappedQteNew
end

local function qteStep()
    local count = 0
    for object, metadata in pairs(qteCallbacks) do
        local obj = object._obj
        if object.Pressed or object._cancelled or not obj or not obj.Parent or tick() >= metadata.Deadline then
            qteCallbacks[object] = nil
        else
            count += 1
            local circle, reference = obj:FindFirstChild("Circle"), obj:FindFirstChild("Reference")
            if circle and reference and circle.Size.X.Scale <= reference.Size.X.Scale * 1.025 then
                if not attemptedQtes[object] then
                    attemptedQtes[object] = true
                    nativeQtePress(object, metadata.Window, metadata.Deadline, object.Mode)
                    S.Actions += 1
                end
            end
        end
    end
    if MODE == "qte" or count > 0 then status("QTE watching " .. count .. " prompts · " .. S.Actions .. " native presses") end
end

local function rewardStep()
    if rewardBusy then return end
    rewardBusy = true
    task.spawn(function()
        local ok, err = pcall(function()
            local rewards = RS.Remotes.Commerce.Rewards
            local data = rewards.GetPlaytimeRewards:InvokeServer()
            if not S.Enabled or type(data) ~= "table" then return end
            local config = require(RS.Config.Rewards.PlaytimeRewardsConfig)
            for index, reward in ipairs(config.Rewards) do
                if not S.Enabled then break end
                if not ((data.Claimed or {})[index] or (data.Claimed or {})[tostring(index)])
                    and (tonumber(data.PlaySeconds) or 0) >= (tonumber(reward.RequiredSeconds) or math.huge) then
                    local result = rewards.ClaimPlaytimeReward:InvokeServer(index)
                    if type(result) == "table" and result.Success then S.Actions += 1 end
                    if type(result) == "table" and result.State then data = result.State end
                end
            end
            if S.Enabled then status("Eligible rewards claimed · " .. S.Actions) end
        end)
        rewardBusy = false
        if not ok and S.Enabled then status("Reward check failed · " .. tostring(err)) end
    end)
end

local function trackerStep()
    if MODE == "bloodmoon" then
        local window = Event.BloodMoonWindow(os.time())
        if window then status("Blood Moon active · " .. math.max(0, window.End - os.time()) .. "s left")
        else
            local nextStart = math.huge
            for _, w in ipairs(Event.BloodMoon.Windows) do if w.Start > os.time() then nextStart = math.min(nextStart, w.Start) end end
            status(nextStart < math.huge and ("Next Blood Moon in " .. math.floor((nextStart - os.time()) / 60) .. " min") or "No upcoming Blood Moon window")
        end
    elseif MODE == "candy" then
        local amount = tonumber(Data:GetValue({"EventsData", Event.EventKey, "Candy"})) or 0
        if S.StartCandy == nil then S.StartCandy = amount end
        status("Candy · " .. amount .. " · change " .. (amount - S.StartCandy) .. " this session")
    elseif MODE == "cooldown" then
        if not dashHandler then dashHandler = nativeDash() end
        if not dashHandler then status("Dash cooldown interface unavailable"); return end
        local values = debug.getupvalues(dashHandler)
        -- Verified native dash closure positions 5 and 6 are cooldown-active and unlocked.
        if type(values[5]) ~= "boolean" or type(values[6]) ~= "boolean" then
            status("Dash state layout changed"); return
        end
        local text = values[5] and "cooldown active" or (values[6] and "ready" or "locked")
        local character = LP.Character
        local timers = {}
        if character then
            local now = workspace:GetServerTimeNow()
            for name, value in pairs(character:GetAttributes()) do
                if name:match("CooldownUntil$") and type(value) == "number" and value > now and value - now < 600 then
                    timers[#timers + 1] = name:gsub("CooldownUntil$", "") .. " " .. math.ceil(value - now) .. "s"
                end
            end
        end
        status("Dash · " .. text .. (#timers > 0 and (" · " .. table.concat(timers, " · ")) or ""))
    end
end

local function stop()
    for _, c in ipairs(connections) do c:Disconnect() end
    table.clear(connections)
    for _, w in pairs(watches) do w.Connection:Disconnect() end
    table.clear(watches)
    table.clear(threats)
    table.clear(markers)
    table.clear(qteCallbacks)
    if qteLibrary and qteLibrary.new == wrappedQteNew then qteLibrary.new = originalQteNew end
    if MODE == "combat" then stopAdvancedCombat() end
    if MODE == "dodgeitem" then stopItemDodge() end
    if folder then folder:Destroy(); folder = nil end
    local h, r = live(S.Moving)
    if h and S.Moving == LP.Character then h:MoveTo(r.Position) end
    S.Moving = nil
end

function S:SetEnabled(enabled)
    self.Generation += 1
    local full = MODE == "qte" and env.__ALLEN_MATCH_combat
    if full and full.Enabled and not full.Destroyed then
        full.QTEEnabled = enabled == true
        self.Status = "Managed by Full Auto Combat"
        return
    end
    local itemOwner = MODE == "dodgeitem" and env.__ALLEN_MATCH_combat
    if itemOwner and itemOwner.Enabled and not itemOwner.Destroyed then
        itemOwner.ItemDodgeEnabled = enabled == true
        self.Status = "Managed by Full Auto Combat"
        return
    end
    self.Enabled = false
    stop()
    if not enabled or self.Destroyed then self.Status = "Off"; return end
    if MODE == "dodge" or MODE == "cooldown" or MODE == "combat" then
        assert(type(getconnections) == "function", "Executor needs native callback inspection")
    end
    if MODE == "qte" then prepareQte() end
    if MODE == "dodgeitem" then
        assert(type(getgc) == "function", "Dodge item inspection needs getgc support")
        prepareItemDodge()
    end
    if MODE == "combat" then
        local ok, err = pcall(function() prepareAdvancedCombat(); prepareQte() end)
        if not ok then stop(); error(err, 0) end
    end
    self.Enabled = true
    if MODE == "dodge" or MODE == "combat" or MODE == "dodgeitem" then
        local event = RS.Remotes.Gameplay.Combat:FindFirstChild("CreateHitbox")
        if event and event:IsA("RemoteEvent") then
            connections[#connections + 1] = event.OnClientEvent:Connect(reportedHitbox)
        end
    end
    prepareVisuals()
    status("Starting " .. MODE)
    local elapsed = 0
    nextScan, nextSlow = 0, 0
    connections[#connections + 1] = Run.Heartbeat:Connect(function(dt)
        local frameMs = dt * 1000
        S.FrameMs = S.FrameMs and S.FrameMs * .9 + frameMs * .1 or frameMs
        elapsed += dt
        if MODE ~= "combat" and MODE ~= "dodge" and MODE ~= "dodgeitem" and elapsed < (MODE == "qte" and 1/30 or .1) then return end
        elapsed = 0
        local now = os.clock()
        local started = os.clock()
        local ok, err = pcall(function()
            if MODE == "combat" then combatStep(now); if self.QTEEnabled then qteStep() end
            elseif MODE == "dodge" then defenseStep(now)
            elseif MODE == "dodgeitem" then itemDodgeStep(now)
            elseif MODE == "qte" then qteStep(now)
            elseif now >= nextSlow then
                nextSlow = now + (MODE == "rewards" and 15 or 1)
                if MODE == "esp" then espStep()
                elseif MODE == "rewards" then rewardStep()
                else trackerStep() end
            end
        end)
        S.MaxStepMs = math.max(S.MaxStepMs or 0, (os.clock() - started) * 1000)
        if not ok then self:SetEnabled(false); self.Status = "Stopped · " .. tostring(err); warn("[Match " .. MODE .. "] " .. tostring(err)) end
    end)
end

function S:GetSnapshot()
    local full = MODE == "qte" and env.__ALLEN_MATCH_combat
    if full and full.Enabled and not full.Destroyed then return {Enabled = full.QTEEnabled, Status = "Managed by Full Auto Combat"} end
    local itemOwner = MODE == "dodgeitem" and env.__ALLEN_MATCH_combat
    if itemOwner and itemOwner.Enabled and not itemOwner.Destroyed then return {Enabled = itemOwner.ItemDodgeEnabled, Status = "Managed by Full Auto Combat"} end
    return {Enabled = self.Enabled, Status = self.Status, Actions = self.Actions,
        Decision = self.Decision, Target = self.TargetName, ObservedAttacks = self.ObservedAttacks,
        AttackRequests = self.AttackRequests, DashRequests = self.DashRequests, JumpRequests = self.JumpRequests,
        ConfirmedAttacks = self.ConfirmedAttacks, ConfirmedDashes = self.ConfirmedDashes,
        DashPunchRequests = self.DashPunchRequests, ConfirmedDashPunches = self.ConfirmedDashPunches,
        MotorFrames = self.MotorFrames, MovedStuds = self.MovedStuds, ConfirmedJumps = self.ConfirmedJumps,
        Navigation = self.Navigation, QTEPresses = self.Actions,
        ItemRequests = self.ItemRequests, ItemAccepted = self.ItemAccepted, ItemDodged = self.ItemDodged,
        ItemMissed = self.ItemMissed, ItemStatus = self.ItemStatus,
        DodgeRevision = self.DodgeRevision, ThreatStatus = self.ThreatStatus, InstantChecks = self.InstantChecks,
        PingMs = self.PingMs, FrameMs = self.FrameMs,
        DamageObserved = self.DamageObserved, MaxStepMs = self.MaxStepMs}
end
function S:Destroy()
    self:SetEnabled(false)
    self.Destroyed = true
    if env[key] == self then env[key] = nil end
end
env[key] = S
return S

end
]====],
SkyProtection=[====[
assert(game.GameId == 8366716517, "Open Sky Fighters")
local Players = game:GetService("Players")
local Run = game:GetService("RunService")
local LP = Players.LocalPlayer
local States = require(game.ReplicatedStorage.Modules.Gameplay.CharacterStateController)
local Policy = (function()
local Policy = {}
function Policy.ShouldRescue(s)
    if not s.Alive or s.Restricted or not s.Safe or s.SafeAge > 8 or s.SinceRescue < 1 then return false end
    if s.Distance > 100 or s.Drop < 4 or s.VerticalSpeed > -12 then return false end
    return s.Hazard or not s.FloorAhead
end
return Policy

end)()
local env = getgenv()
local key = "__ALLEN_SKY_antifall"
if env[key] then env[key]:Destroy() end
local S = {HubOnly=true, Enabled=false, Destroyed=false, Status="Off", Actions=0}
local connection, character, humanoid, root, safe, lastRescue = nil,nil,nil,nil,nil,-math.huge
local elapsed = 0
local function restricted(c)
    return States.HasAny(c,{"CombatDisabled","CutsceneActive","CameraControlDisabled"})
end
local function bind()
    if LP.Character~=character then
        character=LP.Character;safe=nil
        humanoid=character and character:FindFirstChildOfClass("Humanoid")
        root=character and character:FindFirstChild("HumanoidRootPart")
    end
    if character then
        humanoid=character:FindFirstChildOfClass("Humanoid")
        root=character:FindFirstChild("HumanoidRootPart")
    end
    return humanoid and root and humanoid.Health>0 and character.Parent
end
local function antiFall(now)
    if restricted(character) then safe=nil;S.Status="Waiting for round / cutscene";return end
    local exclude={character}
    for _,p in ipairs(Players:GetPlayers()) do if p.Character then exclude[#exclude+1]=p.Character end end
    local params=RaycastParams.new();params.FilterType=Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances=exclude;params.RespectCanCollide=true
    local hit=workspace:Raycast(root.Position,Vector3.new(0,-18,0),params)
    local function hazard(part)return part and (part.Name=="FallPart" or part.Name=="FallKillPart")end
    local grounded=hit and hit.Normal.Y>.65 and not hazard(hit.Instance)
        and (root.Position-hit.Position).Magnitude<=humanoid.HipHeight+4
        and math.abs(root.AssemblyLinearVelocity.Y)<8
        and not States.HasAny(character,{"Ragdolled","Stunned"})
    if grounded then
        safe={Part=hit.Instance,Relative=hit.Instance.CFrame:ToObjectSpace(root.CFrame),At=now}
    end
    if safe and (not safe.Part.Parent or not safe.Part.CanCollide) then safe=nil end
    if not safe then S.Status="Waiting for safe ground";return end
    local destination=safe.Part.CFrame*safe.Relative
    local predicted=root.Position+root.AssemblyLinearVelocity*.15
    local ahead=workspace:Raycast(predicted,Vector3.new(0,-18,0),params)
    if Policy.ShouldRescue({Alive=true,Restricted=false,Safe=true,SafeAge=now-safe.At,
        SinceRescue=now-lastRescue,Distance=(root.Position-destination.Position).Magnitude,
        Drop=destination.Position.Y-root.Position.Y,VerticalSpeed=root.AssemblyLinearVelocity.Y,
        Hazard=hit and hazard(hit.Instance) or ahead and hazard(ahead.Instance),
        FloorAhead=ahead and not hazard(ahead.Instance) and ahead.Normal.Y>.6}) then
